/**
 * Putting a roll's total into a property.
 *
 * Rolling AGAINST a character and rolling one UP are different acts. The
 * plugin has always been good at the first - a d20 plus a modifier, told and
 * forgotten - and useless at the second, where the dice decide what a value
 * IS: `3d6dhdl + 8` into Strength, the same macro again into Dexterity, and
 * the sheet is made.
 *
 * What this does NOT do is bind the property to the dice. The value is
 * written once and is an ordinary number afterwards - editable, steppable,
 * overwritable by hand - because a character generated by dice is not a
 * character who re-rolls their strength every time the note is opened.
 *
 * The write goes through the same path an edit does, so it lands in the undo
 * history and behaves for conflicts like anything else.
 */

import { App, Menu, Notice, TFile } from "obsidian";
import type { I18n } from "../../i18n/i18n";
import type { ViewCtx } from "../../core/context";
import { ConfirmModal } from "../../ui/modals/dialogs";
import { showMenu } from "../../ui/menus/show";

/** Somewhere a total can be put, and what is there at the moment. */
export interface RollTarget {
  /** The property's key, as it was written down. */
  key: string;
  /** What the note holds for that key now, if anything. */
  current: unknown;
  /** Write the number. */
  set: (value: number) => void;
}

/** Whether a value is worth warning about overwriting. */
function occupied(value: unknown): boolean {
  return value !== undefined && value !== null && value !== "" && !(Array.isArray(value) && !value.length);
}

/**
 * Put `total` into `target`, telling the reader it happened.
 *
 * Silent by default, because the usual case is a sheet being rolled up and a
 * dialog per attribute is four dialogs nobody reads - and because the write
 * is undoable, which is a better answer than a question. A macro can ask for
 * the question anyway, and then it is asked only when there is something to
 * lose.
 */
export function putResult(app: App, i18n: I18n, target: RollTarget, total: number, askFirst = false): void {
  const write = (): void => {
    target.set(total);
    new Notice(i18n.t("roll.intoDone", { key: target.key, total: String(total) }), 4000);
  };
  if (!askFirst || !occupied(target.current)) {
    write();
    return;
  }
  new ConfirmModal(
    app,
    i18n,
    i18n.t("roll.intoAsk", { key: target.key, had: String(target.current), total: String(total) }),
    write
  ).open();
}

/**
 * Types a rolled total can be put into.
 *
 * Numbers and the things that are numbers wearing a costume - a rating is a
 * count of pips, a unit is a number with a name after it. Derived values and
 * formulas are deliberately absent: they are worked out rather than stored,
 * and writing to one would either be ignored or would quietly break the
 * arithmetic that produced it.
 */
const SETTABLE = new Set(["number", "decimal", "unit", "rating"]);

/** A property on this note type that a total could be written into. */
export interface NumberTarget {
  key: string;
  label: string;
}

/**
 * Every number-typed property the note's own type holds, in the order the
 * sheet lays them out - which is the order somebody looking at the sheet will
 * expect to find them in.
 */
export function numberTargets(view: ViewCtx): NumberTarget[] {
  const seen = new Set<string>();
  const out: NumberTarget[] = [];
  for (const section of view.layout.sections ?? []) {
    for (const entry of section.entries ?? []) {
      const key = entry.kind === "prop" ? (entry.key ?? "") : "";
      if (!key || seen.has(key.toLowerCase())) continue;
      if (!SETTABLE.has(view.resolveType(entry))) continue;
      seen.add(key.toLowerCase());
      out.push({ key, label: (entry.alias as string) || key });
    }
  }
  return out;
}

/**
 * Offer the note's number properties and put `total` in whichever is picked.
 *
 * The list is the sheet's own, not the vault's: a roll made on a character is
 * being assigned to something that character has.
 */
export function assignMenu(view: ViewCtx, file: TFile, total: number, ev: MouseEvent): void {
  const t = view.i18n.t.bind(view.i18n);
  const targets = numberTargets(view);
  const menu = new Menu();
  if (!targets.length) {
    menu.addItem((i) => i.setTitle(t("roll.assignNone")).setDisabled(true));
  } else {
    menu.addItem((i) => i.setTitle(t("roll.assignTo", { total: String(total) })).setDisabled(true));
    for (const target of targets)
      menu.addItem((i) =>
        i
          .setTitle(target.label)
          .setIcon("check")
          .onClick(() =>
            putResult(
              view.app,
              view.i18n,
              {
                key: target.key,
                current: view.note.raw[target.key],
                set: (value) => view.note.set(file, target.key, value),
              },
              total
            )
          )
      );
  }
  showMenu(menu, ev);
}

/** Where a total could be put: the open sheet, whatever asked for the roll. */
export type AssignSource = () => { view: ViewCtx; file: TFile } | null;

let source: AssignSource | null = null;

/**
 * Tell roll cards where a total could go.
 *
 * A card knows its number and nothing else - it is drawn on a layer over the
 * whole workspace and has never heard of a sheet. Rather than thread a view
 * through every path that can produce one (a button, a macro, a command, the
 * roller), the plugin says once where the open sheet is, and the cards ask.
 */
export function setAssignSource(fn: AssignSource | null): void {
  source = fn;
}

/** Whether there is a sheet open with somewhere to put a number. */
export function canAssignHere(): boolean {
  const src = source?.();
  return !!src && numberTargets(src.view).length > 0;
}

/** Offer the open sheet's number properties for `total`. */
export function assignHere(total: number, ev: MouseEvent): void {
  const src = source?.();
  if (!src) return; // guarded by canAssignHere: nothing open, nothing offered
  assignMenu(src.view, src.file, total, ev);
}
